CREATE TABLE public.course_enrollments (LIKE public.language_profiles INCLUDING DEFAULTS INCLUDING CONSTRAINTS);
ALTER TABLE public.course_enrollments ADD PRIMARY KEY (id);
CREATE UNIQUE INDEX course_enrollments_user_language_course ON public.course_enrollments(user_id,language,course_type);
GRANT SELECT,INSERT,UPDATE ON public.course_enrollments TO authenticated;
GRANT ALL ON public.course_enrollments TO service_role;
ALTER TABLE public.course_enrollments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own course enrollments" ON public.course_enrollments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "Own course enrollment insert" ON public.course_enrollments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND ((language IN ('no','de','en') AND course_type='general' AND level='A2') OR (language IN ('no','de') AND course_type='health' AND level='B1')));
CREATE POLICY "Own course enrollment update" ON public.course_enrollments FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY "Staff course enrollment read" ON public.course_enrollments FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'admin_teacher') OR public.is_teacher_of_student(user_id));
INSERT INTO public.course_enrollments SELECT * FROM public.language_profiles ON CONFLICT(user_id,language,course_type) DO NOTHING;
CREATE FUNCTION public.lock_independent_course_enrollment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') AND (NEW.user_id IS DISTINCT FROM OLD.user_id OR NEW.language IS DISTINCT FROM OLD.language OR NEW.course_type IS DISTINCT FROM OLD.course_type OR NEW.level IS DISTINCT FROM OLD.level) THEN RAISE EXCEPTION 'Upisani kurs i nivo se ne mogu promeniti.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER lock_independent_course_enrollment BEFORE UPDATE ON public.course_enrollments FOR EACH ROW EXECUTE FUNCTION public.lock_independent_course_enrollment();
CREATE TRIGGER course_enrollments_updated_at BEFORE UPDATE ON public.course_enrollments FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE FUNCTION public.sync_legacy_course_enrollment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.course_enrollments(id,user_id,language,level,learning_goal,focus_area,confidence_level,preferred_tone,lives_in_norway,subscription_type,onboarding_completed,created_at,updated_at,life_context,course_type,daily_minutes) VALUES(NEW.id,NEW.user_id,NEW.language,NEW.level,NEW.learning_goal,NEW.focus_area,NEW.confidence_level,NEW.preferred_tone,NEW.lives_in_norway,NEW.subscription_type,NEW.onboarding_completed,NEW.created_at,NEW.updated_at,NEW.life_context,NEW.course_type,NEW.daily_minutes) ON CONFLICT(user_id,language,course_type) DO UPDATE SET level=EXCLUDED.level,learning_goal=EXCLUDED.learning_goal,focus_area=EXCLUDED.focus_area,confidence_level=EXCLUDED.confidence_level,preferred_tone=EXCLUDED.preferred_tone,lives_in_norway=EXCLUDED.lives_in_norway,subscription_type=EXCLUDED.subscription_type,onboarding_completed=EXCLUDED.onboarding_completed,updated_at=EXCLUDED.updated_at,life_context=EXCLUDED.life_context,daily_minutes=EXCLUDED.daily_minutes; RETURN NEW; END $$;
CREATE TRIGGER sync_legacy_course_enrollment AFTER INSERT OR UPDATE ON public.language_profiles FOR EACH ROW EXECUTE FUNCTION public.sync_legacy_course_enrollment();
REVOKE ALL ON FUNCTION public.sync_legacy_course_enrollment() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.can_access_course(_language text,_course text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'admin_teacher') OR EXISTS(SELECT 1 FROM public.course_enrollments WHERE user_id=auth.uid() AND language=_language AND course_type=_course AND onboarding_completed)); $$;
CREATE POLICY "Enrolled lesson level boundary" ON public.course_lessons AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'admin_teacher') OR EXISTS(SELECT 1 FROM public.course_enrollments e WHERE e.user_id=auth.uid() AND e.language=course_lessons.language AND e.course_type=course_lessons.course AND e.onboarding_completed AND (course_lessons.course<>'general' OR substring(e.level FROM '[ABC][12]')=course_lessons.cefr_level)));
COMMENT ON TABLE public.language_profiles IS 'Legacy per-language profiles kept for deployed compatibility and audited enrollment recovery; independent course enrollments live in course_enrollments.';